import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.DpieW3qv.js";const m=JSON.parse('{"title":"Best Practices","description":"","frontmatter":{"title":"Best Practices"},"headers":[],"relativePath":"excel/best-practices.md","filePath":"excel/best-practices.md","lastUpdated":null}'),i={name:"excel/best-practices.md"};function s(n,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h1><p>Guidelines for Web Producers and eComm when using the Excel wireframe and CLI day-to-day.</p><h2 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to &quot;Naming&quot;">​</a></h2><ul><li><strong>Refresh names:</strong> Use clear, date-related names (e.g. &quot;1/26 Winter Sale&quot;, &quot;2/10 3PM Changeout&quot;). Include time when you have multiple refreshes the same day.</li><li><strong>Zones:</strong> Use the exact zone names the system expects (see <a href="./wireframe-format.html">Wireframe format</a> and config). Homepage zones are often normalized to <code>HP_*</code> (e.g. HP_TOP_BANNER, HP_2T).</li><li><strong>IPIDs:</strong> Lowercase, underscores, date segment as MMDDYY at the end. One IPID per item; no duplicates within a refresh.</li></ul><h2 id="approvals-and-sign-off" tabindex="-1">Approvals and sign-off <a class="header-anchor" href="#approvals-and-sign-off" aria-label="Permalink to &quot;Approvals and sign-off&quot;">​</a></h2><ul><li>Confirm content and links in Excel before building. Run <code>make refresh</code> and review reports/detail output before pushing to staging.</li><li>Use your team&#39;s approval process (e.g. sign-off in Smartsheet or email) before running <code>make push</code> for a given date.</li></ul><h2 id="timing" tabindex="-1">Timing <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;Timing&quot;">​</a></h2><ul><li><strong>Pull</strong> at the start of the day or when the Excel/Smartsheet has been updated, so you have the latest refreshes. Pull auto-builds new dates.</li><li><strong>Refresh</strong> after pull to verify content for the selected date.</li><li><strong>Push</strong> after details look correct. Push sends to SFCC staging; use the runbook for staging → production replication in Business Manager.</li><li>Avoid pushing the same date repeatedly without need; use <strong>status</strong> (sticky date) and <strong>reports</strong> for normal day-to-day review.</li></ul><p><strong>Relative to go-live:</strong> Pull and review the day before or morning of go-live so content is ready. Push to staging after sign-off. Replicate in Business Manager when moving to production.</p><h2 id="force-rebuild-policy" tabindex="-1">Force rebuild policy <a class="header-anchor" href="#force-rebuild-policy" aria-label="Permalink to &quot;Force rebuild policy&quot;">​</a></h2><ul><li><strong>After template or HTML edit:</strong> Use <code>make status</code> → &quot;Force rebuild&quot; to regenerate, then <code>make push</code> if that date was already synced (re-sync only what changed).</li><li><strong>After Excel data fix:</strong> Re-run <code>make pull</code> (auto-builds new data), then <code>make refresh</code> to verify, then <code>make push</code>.</li><li><strong>Document force rebuilds:</strong> Note in commit message or runbook when you force-rebuilt so the team knows what was re-pushed.</li></ul><h2 id="multi-producer" tabindex="-1">Multi-producer <a class="header-anchor" href="#multi-producer" aria-label="Permalink to &quot;Multi-producer&quot;">​</a></h2><ul><li>Use <code>make pull</code> to get teammates&#39; work. Use <code>make status</code> to switch dates. Avoid editing the same date/refresh in Excel at the same time; coordinate via your data source (Smartsheet/Excel) and Git.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a> — Command sequence (pull → status → refresh → push)</li><li><a href="/ocapi-docs.github.io/guides/multi-producer.html">Multi-Producer</a> — Sharing a brand</li><li><a href="./validation-and-fixes.html">Validation and fixes</a> — Fixing errors in Excel</li></ul>',15)])])}const g=t(i,[["render",s]]);export{m as __pageData,g as default};
